function errors(){const list=[...(B?.errors||[]),...(latestStatus.errors||[])];const seen=new Set();return list.filter(e=>{let k=e.source+'|'+e.detail;if(seen.has(k))return false;seen.add(k);return true;}).sort((a,b)=>(b.severity==='error')-(a.severity==='error'));}
